// Runnable demo: non-blocking retry stages with growing backoff, classify, DLT.
package com.bank.settlement.demo;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class RetryableTopicDemo {

    private static final Logger log = Logger.getLogger("RetryTopic");
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        DltHandlerSim dlt = new DltHandlerSim();
        SettlementRetryListener listener = new SettlementRetryListener();
        // attempts=4 → main + retry-0 + retry-1 + retry-2 → dlt; backoff 1s x2.0
        RetryableTopicSim topics = new RetryableTopicSim(4, 1000L, 2.0, listener, dlt);

        List<TxnEvent> events = List.of(
            new TxnEvent("TXN-1", "SAV2001", new BigDecimal("20000")), // transient, recovers
            new TxnEvent("TXN-2", "BAD-ACCT", new BigDecimal("50000")) // permanent, straight to DLT
        );

        for (TxnEvent e : events) topics.process(e);

        log.info(() -> "DLT total = " + dlt.count());
    }
}

// ─── Would be in TxnEvent.java ───
class TxnEvent {
    final String txnId;
    final String accountId;
    final BigDecimal amount;
    TxnEvent(String txnId, String accountId, BigDecimal amount) {
        this.txnId = txnId; this.accountId = accountId; this.amount = amount;
    }
}

class TransientScoringException extends RuntimeException {
    TransientScoringException(String m) { super(m); }
}
class ValidationException extends RuntimeException {   // permanent, non-retryable
    ValidationException(String m) { super(m); }
}

// ─── Would be in SettlementRetryListener.java ───
class SettlementRetryListener {
    private static final Logger log = Logger.getLogger("RetryTopic");
    private int txn1Attempts = 0;

    void onTxn(TxnEvent e) {
        if ("BAD-ACCT".equals(e.accountId)) {
            throw new ValidationException("unknown account " + e.accountId); // permanent
        }
        if ("TXN-1".equals(e.txnId) && txn1Attempts++ < 2) {
            throw new TransientScoringException("fraud service busy for " + e.txnId); // transient
        }
        log.info(() -> "settled txn=" + e.txnId + " account=" + e.accountId
                + " amount=Rs." + e.amount);
    }
}

