// Models @RetryableTopic: main topic + retry topics + DLT, classify + bounded attempts.
class RetryableTopicSim {
    private static final Logger log = Logger.getLogger("RetryTopic");
    private final int attempts;
    private final long initialBackoffMs;
    private final double multiplier;
    private final SettlementRetryListener listener;
    private final DltHandlerSim dlt;

    RetryableTopicSim(int attempts, long initialBackoffMs, double multiplier,
                      SettlementRetryListener listener, DltHandlerSim dlt) {
        this.attempts = attempts;
        this.initialBackoffMs = initialBackoffMs;
        this.multiplier = multiplier;
        this.listener = listener;
        this.dlt = dlt;
    }

    void process(TxnEvent e) {
        long backoff = initialBackoffMs;
        for (int attempt = 1; attempt <= attempts; attempt++) {
            String stage = (attempt == 1) ? "main topic" : "retry-" + (attempt - 2);
            final int a = attempt;
            final String s = stage;
            try {
                log.fine(() -> "processing " + e.txnId + " on " + s + " (attempt " + a + ")");
                listener.onTxn(e);
                return;  // success, main flow is NOT blocked by this record
            } catch (ValidationException permanent) {
                // classified non-retryable → skip all retry stages
                log.severe(() -> "permanent failure " + e.txnId + ": " + permanent.getMessage()
                        + " → DLT (no retries)");
                dlt.accept(e, permanent.getMessage());
                return;
            } catch (TransientScoringException transientEx) {
                if (attempt < attempts) {
                    final long b = backoff;
                    log.warning(() -> "transient failure " + e.txnId + " on " + s
                            + "; forward to retry-" + (a - 1) + " after " + b + "ms backoff");
                    backoff = (long) (backoff * multiplier);
                } else {
                    log.severe(() -> "attempts exhausted for " + e.txnId + " → DLT");
                    dlt.accept(e, transientEx.getMessage());
                }
            }
        }
    }
}

// ─── Would be in DltHandlerSim.java (models @DltHandler) ───
class DltHandlerSim {
    private static final Logger log = Logger.getLogger("RetryTopic");
    private int count = 0;
    void accept(TxnEvent e, String reason) {
        count++;
        log.severe(() -> "@DltHandler persisted dead letter txn=" + e.txnId
                + " reason=" + reason);
    }
    int count() { return count; }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
